简单选择排序思路 把数组分成两部分：前面是已排序部分，后面是未排序部分。 一开始，已排序部分为空，未排序部分是整个数组。 每一轮，从未排序部分里找到最小的数，设中间量为k，记录最小值的下标。 根据下标把这个最小的数和未排序部分的第一个数交换。 重复上面的过程，直到未排序部分只剩一个元素为止。 代码实现12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455#include &lt;stdio.h&gt;// 打印数组void printArray(int *arr, int n)&#123; for (int i = 0; i &lt; n; i++) &#123; printf(&quot;%d &quot;, *(arr + i)); &#125; printf(&quot;
&quot;);&#125;// 选择排序void selectionSort(int *arr, int n)&#123; // i 表示未排序部分的第一个元素的下标 for (int i = 0; i &lt; n - 1; i++) &#123; // 先假设未排序部分的第一个元素是最小的 int minIndex = i; // 从 i + 1 开始，在未排序部分里找真正的最小值 for (int j = i + 1; j &lt; n; j++) &#123; if (*(arr + j) &lt; *(arr + minIndex)) &#123; minIndex = j; &#125; &#125; // 如果最小值不在 i 位置，就交换 if (minIndex != i) &#123; int temp = *(arr + i); *(arr + i) = *(arr + minIndex); *(arr + minIndex) = temp; &#125; &#125;&#125;int main()&#123; int arr[] = &#123;5, 3, 8, 4, 2, 7, 1, 6&#125;; int n = sizeof(arr) / sizeof(arr[0]); printf(&quot;排序前：&quot;); printArray(arr, n); selectionSort(arr, n); printf(&quot;排序后：&quot;); printArray(arr, n); return 0;&#125; 运行结果12排序前：5 3 8 4 2 7 1 6排序后：1 2 3 4 5 6 7 8 直接插入排序思路 把数组分成两部分：前面是已排序部分，后面是未排序部分。 一开始，已排序部分只有第一个元素。 从第二个元素开始，依次取出当前元素，当作“待插入的值”，将待插入的值用中间量key保存。 在已排序部分里，从后往前找合适的位置。 如果已排序部分里的元素比待插入的值大，就把它往后挪一位。 找到合适位置后，把待插入的值放进去。 重复上面的过程，直到所有元素都插入完成。 代码实现12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152#include &lt;stdio.h&gt;// 打印数组void printArray(int *arr, int n)&#123; for (int i = 0; i &lt; n; i++) &#123; printf(&quot;%d &quot;, *(arr + i)); &#125; printf(&quot;
&quot;);&#125;// 插入排序void insertionSort(int *arr, int n)&#123; // i 表示当前要插入的元素的下标 // 从第二个元素开始，因为第一个元素默认已经排好 for (int i = 1; i &lt; n; i++) &#123; // 保存当前要插入的值 int key = *(arr + i); // j 表示已排序部分的最后一个元素的下标 int j = i - 1; // 从后往前找，如果已排序部分的元素比 key 大，就往后挪 while (j &gt;= 0 &amp;&amp; *(arr + j) &gt; key) &#123; *(arr + j + 1) = *(arr + j); j--; &#125; // 把 key 放到空出来的位置 *(arr + j + 1) = key; &#125;&#125;int main()&#123; int arr[] = &#123;5, 3, 8, 4, 2, 7, 1, 6&#125;; int n = sizeof(arr) / sizeof(arr[0]); printf(&quot;排序前：&quot;); printArray(arr, n); insertionSort(arr, n); printf(&quot;排序后：&quot;); printArray(arr, n); return 0;&#125; 运行结果12排序前：5 3 8 4 2 7 1 6排序后：1 2 3 4 5 6 7 8 冒泡排序思路 从第一个元素开始，比较相邻的两个元素。 如果前一个比后一个大，就交换它们。 继续比较下一对，直到这一轮结束。这一轮结束后，最大的数会跑到最后。 重复上面的过程，每轮都会把当前未排序部分最大的数放到后面。 一共进行 n - 1 轮，数组就有序了。 代码实现123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051#include &lt;stdio.h&gt;// 打印数组void printArray(int *arr, int n)&#123; for (int i = 0; i &lt; n; i++) &#123; printf(&quot;%d &quot;, *(arr + i)); &#125; printf(&quot;
&quot;);&#125;// 冒泡排序void bubbleSort(int *arr, int n)&#123; int i, j; int temp; // 一共需要 n - 1 轮 for (i = 0; i &lt; n - 1; i++) &#123; // 每一轮比较相邻两个元素 // 后面 i 个元素已经排好了，不用再比较 for (j = 0; j &lt; n - 1 - i; j++) &#123; // 如果前一个比后一个大，就交换 if (*(arr + j) &gt; *(arr + j + 1)) &#123; temp = *(arr + j); *(arr + j) = *(arr + j + 1); *(arr + j + 1) = temp; &#125; &#125; &#125;&#125;int main()&#123; int arr[] = &#123;5, 3, 8, 4, 2, 7, 1, 6&#125;; int n = sizeof(arr) / sizeof(arr[0]); printf(&quot;排序前：&quot;); printArray(arr, n); bubbleSort(arr, n); printf(&quot;排序后：&quot;); printArray(arr, n); return 0;&#125; 运行结果12排序前：5 3 8 4 2 7 1 6排序后：1 2 3 4 5 6 7 8 快速排序思路 选枢轴在当前要排序的区间里，随便选一个数当枢轴。这里选最左边的数：pivot = *left;选完后，left 这个位置就相当于一个“坑”。 确定 left 和 rightleft 指向当前区间的第一个元素。right 指向当前区间的最后一个元素。 用两个指针从两边往中间走i 从左边开始往右走。j 从右边开始往左走。 循环填坑从右往左找，找到第一个小于枢轴的数，把它填到左边的坑里，然后 i 往右移。从左往右找，找到第一个大于枢轴的数，把它填到右边的坑里，然后 j 往左移。 枢轴归位把一开始保存的 pivot 填到 i 和 j 相遇的位置。此时，枢轴左边都比它小，右边都比它大。 递归左右两边对枢轴左边的区间再做一次快速排序。对枢轴右边的区间再做一次快速排序。 代码实现1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071727374#include &lt;stdio.h&gt;// 打印数组void printArray(int *arr, int n)&#123; for (int i = 0; i &lt; n; i++) printf(&quot;%d &quot;, arr[i]); printf(&quot;
&quot;);&#125;// 快速排序void quickSort(int *left, int *right)&#123; // 如果区间没有元素，或者只有一个元素，就不排序 if (left &gt;= right) return; // 1. 选枢轴，保存起来（选最左边的数保存起来） int pivot = *left; // 2. 确定两个指针 int *i = left; // i 从左往右走 int *j = right; // j 从右往左走 // 3. 开始填坑 while (i &lt; j) &#123; // 从右往左找，找到第一个小于枢轴的数 while (i &lt; j &amp;&amp; *j &gt;= pivot) j--; // 找到后，把它填到左边的坑里 if (i &lt; j) &#123; *i = *j; i++; &#125; // 从左往右找，找到第一个大于枢轴的数 while (i &lt; j &amp;&amp; *i &lt;= pivot) i++; // 找到后，把它填到右边的坑里 if (i &lt; j) &#123; *j = *i; j--; &#125; &#125; // 4. 枢轴归位，此时 i 和 j 相遇，把枢轴填到相遇位置 *i = pivot; // 5. 递归排序左边和右边 quickSort(left, i - 1); quickSort(i + 1, right);&#125;int main()&#123; int arr[] = &#123;5, 3, 8, 4, 2, 7, 1, 6&#125;; int n = sizeof(arr) / sizeof(arr[0]); printf(&quot;排序前：&quot;); printArray(arr, n); // arr 是第一个元素的地址，arr + n - 1 是最后一个元素的地址 quickSort(arr, arr + n - 1); printf(&quot;排序后：&quot;); printArray(arr, n); return 0;&#125; 运行结果12排序前：5 3 8 4 2 7 1 6排序后：1 2 3 4 5 6 7 8 堆排序思路堆（Heap）是满足以下两个条件的完全二叉树： 结构条件：是一棵完全二叉树； 堆序条件： 大顶堆：父节点 ≥ 左右孩子（堆顶是最大值） 小顶堆：父节点 ≤ 左右孩子（堆顶是最小值）升序排序用大顶堆，降序排序用小顶堆。堆是逻辑上的二叉树，物理上用数组存储，不需要指针建树。 从下标 1 开始：数组与树的关系 数组开 n + 1 个； arr[0] 不使用（空着或当哨兵）； 有效元素为 arr[1] ~ arr[n]。设当前节点下标为 i： 关系 公式 父节点 i / 2（整数除法） 左孩子 2 * i 右孩子 2 * i + 1 最后一个非叶子节点 n / 2 第一个叶子节点 n / 2 + 1 堆排序整体思路 建大顶堆从最后一个非叶子节点 n / 2 开始，倒着到 1，依次对每个节点执行 heapify（向下调整）： 12for (int i = n / 2; i &gt;= 1; i--) heapify(arr, n, i); 为什么从 n / 2 开始？下标大于 n / 2 的节点全是叶子节点，叶子节点没有孩子，天然满足堆性质，无需调整。调整完后，整个数组满足大顶堆性质，arr[1] 就是全局最大值。 排序（反复取堆顶）循环 i 从 n 递减到 2： 交换 arr[1]（堆顶，当前最大值）与 arr[i]（堆的最后一个元素）； 交换后 arr[i] 已经是本轮的最终位置，堆的大小减为 i - 1； 对新的堆顶元素 arr[1] 执行 heapify(arr, i - 1, 1)，恢复大顶堆； 重复直到堆中只剩一个元素。 12345for (int i = n; i &gt; 1; i--)&#123; swap(&amp;arr[1], &amp;arr[i]); heapify(arr, i - 1, 1);&#125; 循环结束后，arr[1..n] 就是升序序列。 核心操作：heapify（向下调整）含义：假设以 i 为根的左右子树已经是大顶堆，只调整以 i 为根的子树，使其重新成为大顶堆。步骤： 令 largest = i； 若左孩子 2i &lt;= n 且 arr[2i] &gt; arr[largest]，则 largest = 2i； 若右孩子 2i + 1 &lt;= n 且 arr[2i + 1] &gt; arr[largest]，则 largest = 2i + 1； 若 largest != i，交换 arr[i] 与 arr[largest]，并递归&#x2F;迭代对 largest 位置继续操作； 若 largest == i，说明 i 已经是三者最大，停止。递归版： 1234567891011121314151617void heapify(int arr[], int n, int i)&#123; int largest = i; int left = 2 * i; int right = 2 * i + 1; if (left &lt;= n &amp;&amp; arr[left] &gt; arr[largest]) largest = left; if (right &lt;= n &amp;&amp; arr[right] &gt; arr[largest]) largest = right; if (largest != i) &#123; swap(&amp;arr[i], &amp;arr[largest]); heapify(arr, n, largest); &#125;&#125; 迭代版： 1234567891011121314151617181920void heapify(int arr[], int n, int i)&#123; while (1) &#123; int largest = i; int left = 2 * i; int right = 2 * i + 1; if (left &lt;= n &amp;&amp; arr[left] &gt; arr[largest]) largest = left; if (right &lt;= n &amp;&amp; arr[right] &gt; arr[largest]) largest = right; if (largest == i) break; swap(&amp;arr[i], &amp;arr[largest]); i = largest; &#125;&#125; 代码实现123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869#include &lt;stdio.h&gt;// 交换两个整数void swap(int *a, int *b)&#123; int temp = *a; *a = *b; *b = temp;&#125;// 打印 arr[1..n]void printArray(int arr[], int n)&#123; for (int i = 1; i &lt;= n; i++) printf(&quot;%d &quot;, arr[i]); printf(&quot;
&quot;);&#125;// 向下调整：使以 i 为根的子树成为大顶堆// 有效元素为 arr[1..n]，arr[0] 不使用void heapify(int arr[], int n, int i)&#123; int largest = i; int left = 2 * i; int right = 2 * i + 1; if (left &lt;= n &amp;&amp; arr[left] &gt; arr[largest]) largest = left; if (right &lt;= n &amp;&amp; arr[right] &gt; arr[largest]) largest = right; if (largest != i) &#123; swap(&amp;arr[i], &amp;arr[largest]); heapify(arr, n, largest); &#125;&#125;// 堆排序（升序）// arr[1..n] 是有效元素，arr[0] 不用void heapSort(int arr[], int n)&#123; // 1. 建大顶堆：从最后一个非叶子节点 n/2 到 1 for (int i = n / 2; i &gt;= 1; i--) heapify(arr, n, i); // 2. 依次把堆顶最大值放到末尾，再恢复堆 for (int i = n; i &gt; 1; i--) &#123; swap(&amp;arr[1], &amp;arr[i]); heapify(arr, i - 1, 1); &#125;&#125;int main()&#123; int arr[] = &#123;0, 12, 11, 13, 5, 6, 7&#125;; int n = sizeof(arr) / sizeof(arr[0]) - 1; // 实际元素个数 printf(&quot;排序前：&quot;); printArray(arr, n); heapSort(arr, n); printf(&quot;排序后：&quot;); printArray(arr, n); return 0;&#125; 运行结果12排序前：12 11 13 5 6 7排序后：5 6 7 11 12 13
